mapper.select:
SELECT BS.id, BS.screen_code, BS.screen_name, BS.thumbnail, BS.status, BS.publish_time, BS.remark, BS.create_by, COALESCE(NULLIF(SUA.nick_name, ''), SUA.user_name) AS create_name, BS.create_time, BS.update_by, COALESCE(NULLIF(SUB.nick_name, ''), SUB.user_name) AS update_name, BS.update_time FROM vis_screen BS LEFT JOIN sys_account SUA ON BS.create_by = SUA.user_name LEFT JOIN sys_account SUB ON BS.update_by = SUB.user_name
AND BS.screen_name LIKE #{screenName}
AND BS.screen_code LIKE #{screenCode}
AND BS.status = #{screen.status}
ORDER BY BS.create_time DESC
